pub fn main(init: std.process.Init) !void {
    const io = init.io;
    var stdout_writer = std.Io.File.stdout().writer(io, &.{});
    const stdout = &stdout_writer.interface;
    for (1..101) |i| {
        switch (FizzBuzz{ .a = i % 3 == 0, .b = i % 5 == 0 }) {
            .fizzbuzz => try stdout.writeAll("FizzBuzz\n"),
            .fizz => try stdout.writeAll("Fizz\n"),
            .buzz => try stdout.writeAll("Buzz\n"),
